{
  "table": "crm_contacts",
  "columns": [
    {
      "target": "contact_id",
      "source": [
        "Record ID"
      ],
      "transform": "text",
      "params": {
        "case": "upper"
      },
      "confidence": 1.0,
      "note": "Maps Record ID to contact_id."
    },
    {
      "target": "full_name",
      "source": [
        "First Name",
        "Last Name"
      ],
      "transform": "concat",
      "params": {},
      "confidence": 1.0,
      "note": "Combines First Name and Last Name into First Last format."
    },
    {
      "target": "email",
      "source": [
        "E-mail"
      ],
      "transform": "text",
      "params": {
        "case": "lower"
      },
      "confidence": 1.0,
      "note": "Email address, normalised to lowercase."
    },
    {
      "target": "phone",
      "source": [
        "Mobile"
      ],
      "transform": "phone_e164",
      "params": {
        "country": "64"
      },
      "confidence": 0.95,
      "note": "Converts phone number to E.164 format with default NZ country code."
    },
    {
      "target": "company",
      "source": [
        "Organisation"
      ],
      "transform": "text",
      "params": {},
      "confidence": 1.0,
      "note": "Maps organisation to company."
    },
    {
      "target": "created_on",
      "source": [
        "Date Created"
      ],
      "transform": "date",
      "params": {
        "format": "%d-%b-%Y"
      },
      "confidence": 1.0,
      "note": "Parses date created using %d-%b-%Y format."
    },
    {
      "target": "lifetime_value",
      "source": [
        "Total Spend"
      ],
      "transform": "number",
      "params": {
        "decimal": ".",
        "thousands": ","
      },
      "confidence": 1.0,
      "note": "Parses monetary total spend into decimal."
    }
  ],
  "ignore": {
    "Notes": "Notes column is entirely empty in the new file."
  },
  "review": [
    "Name column split into First Name and Last Name; successfully remapped using concat transform.",
    "Notes column is now completely empty in the source file and has been ignored."
  ],
  "author": "model"
}
